const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometry for Gulf of Mexico off southwestern Florida
  const region = ee.Geometry.Polygon([
    [[-83, 25], [-83, 27], [-81, 27], [-81, 25], [-83, 25]]
  ]);

  // 2. Data acquisition for both dates
  const oct30 = ee.ImageCollection('NASA/OCEANDATA/MODIS-Aqua/L3SMI')
    .filterDate('2004-10-30', '2004-10-31')
    .filterBounds(region)
    .select('chlor_a');

  const nov21 = ee.ImageCollection('NASA/OCEANDATA/MODIS-Aqua/L3SMI')
    .filterDate('2004-11-21', '2004-11-22')
    .filterBounds(region)
    .select('chlor_a');

  const octSize = oct30.size().getInfo();
  const novSize = nov21.size().getInfo();

  console.log(`October 30 images: ${octSize}`);
  console.log(`November 21 images: ${novSize}`);

  // Check if collections are empty
  if (octSize === 0 || novSize === 0) {
    console.log('Missing data for one or both dates');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Get images and calculate mean chlorophyll
  const octImg = oct30.first();
  const novImg = nov21.first();

  // Count valid pixels
  const octCount = octImg.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 4000,
    maxPixels: 1e9
  }).get('chlor_a').getInfo();

  const novCount = novImg.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 4000,
    maxPixels: 1e9
  }).get('chlor_a').getInfo();

  console.log(`October 30 valid pixels: ${octCount}`);
  console.log(`November 21 valid pixels: ${novCount}`);

  if (octCount === 0 || novCount === 0) {
    console.log('No valid pixels after processing');
    console.log('<answer>C2</answer>');
    return;
  }

  // 4. Calculate mean chlorophyll concentration
  const octMean = octImg.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 4000,
    maxPixels: 1e9
  }).get('chlor_a').getInfo();

  const novMean = novImg.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 4000,
    maxPixels: 1e9
  }).get('chlor_a').getInfo();

  console.log(`October 30 mean chlor_a: ${octMean}`);
  console.log(`November 21 mean chlor_a: ${novMean}`);

  // 5. Validation and final answer
  if (octMean === null || novMean === null || isNaN(octMean) || isNaN(novMean)) {
    console.log('Calculation failed - invalid result');
    console.log('<answer>C3</answer>');
    return;
  }

  if (octMean < 0 || novMean < 0 || octMean > 100 || novMean > 100) {
    console.log('Invalid chlorophyll range');
    console.log('<answer>C3</answer>');
    return;
  }

  // Compare values
  if (novMean > octMean) {
    console.log(`Increase: Nov (${novMean.toFixed(3)}) > Oct (${octMean.toFixed(3)})`);
    console.log('<answer>A</answer>');
  } else {
    console.log(`No increase: Nov (${novMean.toFixed(3)}) <= Oct (${octMean.toFixed(3)})`);
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
